import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"跟做：共享知识库与权限继承","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/library-grants.md","filePath":"tutorials/library-grants.md"}'),i={name:"tutorials/library-grants.md"};function d(n,a,l,o,p,h){return t(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="跟做-共享知识库与权限继承" tabindex="-1">跟做：共享知识库与权限继承 <a class="header-anchor" href="#跟做-共享知识库与权限继承" aria-label="Permalink to &quot;跟做：共享知识库与权限继承&quot;">​</a></h1><p>个人写作仍然是注册后点击“我的文档”，直接保存第一篇正文。本章增加共享空间：Owner/Admin 从首页“知识库”创建共享库、修改库名，并选择已经注册的成员授予只读或编辑权限。</p><h2 id="_1-用两个账号跟做" tabindex="-1">1. 用两个账号跟做 <a class="header-anchor" href="#_1-用两个账号跟做" aria-label="Permalink to &quot;1. 用两个账号跟做&quot;">​</a></h2><ol><li>用 Owner 登录，进入“知识库”，创建“团队手册”。点击库内“新建文档”，保存一篇 Markdown。</li><li>用另一个浏览器注册同事账号。此时不能直接读取刚才的文档，也看不到对应共享库。</li><li>Owner 从文档点击“所在知识库”，在“知识库授权”选择同事，保存“只读”。</li><li>同事从首页“知识库”打开共享库，能搜索和阅读文档，无法新建或编辑。</li><li>Owner 把同事改为“可编辑”。同事刷新后可以新建或显式修改文档。</li><li>Owner 撤销授权。同事后续查询库、搜索、读取或保存都会被拒绝；刷新页面可看到拒绝结果。</li></ol><p>角色变更由服务端判定，不需要退出再登录。已打开的内容不会被远程擦除；后续 API 请求按当前授权执行，页面在重新查询或恢复焦点时取得新状态。本章不引入实时权限推送。</p><h2 id="_2-谁可以做什么" tabindex="-1">2. 谁可以做什么 <a class="header-anchor" href="#_2-谁可以做什么" aria-label="Permalink to &quot;2. 谁可以做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资格</th><th>库内阅读/搜索</th><th>文档写入</th><th>创建共享库、改名、授权</th></tr></thead><tbody><tr><td>Owner / Admin</td><td>全部知识库</td><td>全部知识库</td><td>允许</td></tr><tr><td>Member + Reader</td><td>已授权库</td><td>拒绝</td><td>拒绝</td></tr><tr><td>Member + Editor</td><td>已授权库</td><td>已授权库</td><td>拒绝</td></tr><tr><td>Member 无 Grant</td><td>不可见</td><td>不可见</td><td>拒绝</td></tr></tbody></table><p>个人库也使用同一套 Grant，第一次保存时自动准备 Editor，不会因为新功能自动公开给其他普通用户。Owner/Admin 按已确认模型仍可管理和读取所有个人库。给管理员分配 Reader 不会降低其企业角色已有的权限。</p><p>知识库删除与文件清理由后续删除章节实现；本章管理名称、访问范围与授权。</p><h2 id="_3-授权决定数据查询与写入" tabindex="-1">3. 授权决定数据查询与写入 <a class="header-anchor" href="#_3-授权决定数据查询与写入" aria-label="Permalink to &quot;3. 授权决定数据查询与写入&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/crates/app/src/modules/knowledge/bases.rs" target="_blank" rel="noreferrer">知识库接口与用例</a>提供可见列表、创建、详情和改名。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/crates/app/src/modules/knowledge/grants.rs" target="_blank" rel="noreferrer">Grant 用例</a>负责授权列表、授予和撤销。授予与撤销都和 Audit 同事务提交；没有实际变化的重复操作不会重复追加授权事件。</p><p>文档列表 API 增加可选 <code>knowledge_base_id</code>；不传时仍是个人空间。创建文档也可指定目标库。列表仅返回摘要，标题搜索仍转义 <code>%</code>、<code>_</code> 与反斜杠。游标绑定账号、库范围、筛选和排序，换库必须重新查询。</p><p>不可见文档或库返回 404；可读但不允许写入返回 403。Read / List / Search / Create / Update 都在后端验证，不能通过隐藏按钮、直接输入 URL 或复用 cursor 绕过。</p><p>每次响应中的 <code>can_edit / can_manage / can_create</code> 是服务端当前判断。个人文档列表也返回当前 <code>can_create</code>，无个人库时允许首次写作，已有库撤权后则禁止重新初始化绕过。前端只用这些标记改善体验；真正执行 mutation 时仍重新验证。GrantAccess 与相关 SDK 类型由 Rust 合同生成，前端不维护另一套角色推导规则。</p><h2 id="_4-撤权与正在执行的保存如何排序" tabindex="-1">4. 撤权与正在执行的保存如何排序 <a class="header-anchor" href="#_4-撤权与正在执行的保存如何排序" aria-label="Permalink to &quot;4. 撤权与正在执行的保存如何排序&quot;">​</a></h2><p>普通文档写入先持有当前 Membership 的共享锁，再持有 Knowledge Base 的共享锁，检查权限并保存。库授权变更通过 Organization 的<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">有序成员锁接口</a>同时锁定操作者和目标成员，再取库的排他锁。</p><p>如果保存已经取得库锁，撤权会等这次保存完成，再提交撤销；撤权提交后开始的请求不能继续写入。反过来，撤权先取得锁时，后续保存读取到无 Grant 并被拒绝。授权缓存或幂等结果不能跳过这一步。</p><p>涉及多个成员时按成员 ID 顺序取锁，和企业成员管理保持一致；新增附件或任务授权也要遵守这个提交顺序。Core 不读取 Knowledge 表，参考业务通过公开 Core 接口协作。</p><h2 id="_5-页面与缓存" tabindex="-1">5. 页面与缓存 <a class="header-anchor" href="#_5-页面与缓存" aria-label="Permalink to &quot;5. 页面与缓存&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/packages/views/src/knowledge/knowledge-bases-view.tsx" target="_blank" rel="noreferrer">知识库 Views</a>复用 Core 成员目录选择已注册用户，无邀请步骤。个人文档与库内文档使用同一个<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/packages/views/src/knowledge/documents-view.tsx" target="_blank" rel="noreferrer">列表/编辑 View</a>；库范围进入 Query key 与 API 参数，未保存草稿也按账号和库分开。</p><p>Reader 看到只读页面，即使直接打开编辑 URL，保存控件也不可用。保存收到 403/404 后立即禁用再次提交并重新读取权限，未保存文本保持原样；只有显式点击“重新查询权限”且服务器确认恢复写入资格后，才重新允许保存。权限重新读取失败时也不能据旧的界面权限继续提交。所有已保存资源仍由 Query 管理，不复制到第二份业务 store。</p><p>库、授权和成员列表默认每页 50、最大 100 条。页面提供“加载更多”和失败重读，浏览器每组列表最多保留十页，避免无限增长。后台系统不会向普通用户先返回全部库，再让前端过滤。</p><h2 id="_6-从公开入口验证" tabindex="-1">6. 从公开入口验证 <a class="header-anchor" href="#_6-从公开入口验证" aria-label="Permalink to &quot;6. 从公开入口验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/knowledge-bases.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>真实 PostgreSQL 测试覆盖角色/Grant 矩阵、不可见搜索、改名、范围绑定、授权审计回滚与撤权/写入锁竞争。View 验证创建共享库→库内保存、授权/撤销、改名，以及 Reader 的页面和直接编辑入口。</p><p>关键流程完成时集中运行一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/knowledge-grants.spec.ts</span></span></code></pre></div><p>两个真实浏览器经历不可见→Reader→Editor→撤权，既验证页面，也验证 Cookie、生成 SDK、服务端授权与实际数据库。</p><p>本章只扩展知识库参考业务；库模型、API、Views、契约符号、测试与教程均登记在<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">所有权清单</a>。Core 的有序成员锁和成员目录会保留。后续附件使用同一库级授权边界，不增加逐文件 ACL。</p><hr><p>源码版本：<code>14acdb0c78d3</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/14acdb0c78d3ec91abf486504116982dcd373c9f/docs/tutorials/07-library-grants.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,31)])])}const k=e(i,[["render",d]]);export{b as __pageData,k as default};
